// Copies the Astro build of "/" and "/en/" into the repository root, which GitHub Pages serves.
// The guides in the root are generated by _src/build.py and are never touched here.
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const web = join(dirname(fileURLToPath(import.meta.url)), "..");
const dist = join(web, "dist");
const root = join(web, "..");

const pages = ["index.html", "en/index.html"];
for (const page of pages) {
  const from = join(dist, page);
  if (!existsSync(from)) throw new Error(`Missing build output: ${from}`);
  const html = readFileSync(from, "utf8");
  if (!html.includes("THESIS:")) throw new Error(`Direction contract missing from ${page}`);
}

// Assets are content-hashed, so the old folder is replaced as a whole.
rmSync(join(root, "_astro"), { recursive: true, force: true });
cpSync(join(dist, "_astro"), join(root, "_astro"), { recursive: true });

for (const page of pages) {
  mkdirSync(dirname(join(root, page)), { recursive: true });
  cpSync(join(dist, page), join(root, page));
}
console.log(`Published ${pages.join(", ")} and _astro/ to ${root}`);
